local a={}a.CFG={degPerCell=3,tickEvery=10,labelEvery=30,tickCh="|"}local b={[0]="N",[90]="E",[180]="S",[270]="W"}local function c(d)return math.floor(d+0.5)end;function a.norm360(e)local f=e%360;if f<0 then f=f+360 end;return f end;function a.signedDelta(g,h)return(g-h+180)%360-180 end;function a.lubberCol(i)return math.ceil(i/2)end;function a.lubberLabel(j)if type(j)~="number"then return"---"end;return string.format("%03d",c(a.norm360(j))%360)end;local function k(l,m,n)for o=1,#n do local p=m+o-1;if p>=1 and p<=#l then l[p]=n:sub(o,o)end end end;function a.row(j,i,q)q=q or a.CFG;if type(i)~="number"or i<1 then return""end;if type(j)~="number"then return string.rep(" ",i)end;local l={}for o=1,i do l[o]=" "end;local r=a.lubberCol(i)local s=math.floor(i/2)*q.degPerCell+q.labelEvery;local t=c(j/q.tickEvery)*q.tickEvery;for u=t-s,t+s,q.tickEvery do local m=r+c(a.signedDelta(u,j)/q.degPerCell)k(l,m,q.tickCh)end;local v=c(j/q.labelEvery)*q.labelEvery;for u=v-s,v+s,q.labelEvery do local w=a.norm360(u)local x=b[w]or string.format("%02d",c(w/10)%36)local m=r+c(a.signedDelta(u,j)/q.degPerCell)k(l,m-math.floor(#x/2),x)end;return table.concat(l)end;return a